package net.officefloor.hq.app.claim;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Types;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims of each sheet, newest first: by when each was added, or last reassigned to another person. */
@Repository
public class Claims {

    private static final String COLUMNS = "SELECT id, sheet_id, person_id, amount, claim_date, note, status, number, due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, split_from, locked_by, late_entry, reminded_on, ref, tags, tags_used, void_reason, edited_by, due_terms, batch, "
            + "(SELECT today FROM sheet WHERE sheet.id = claim.sheet_id) AS sheet_today FROM claim";

    private final JdbcTemplate jdbc;

    public Claims(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> onSheet(String sheetId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY listed DESC", Claims::claim, sheetId);
    }

    /** The claim with this id on this sheet, or null when there is none. Locks the claim's row for
     *  the rest of the transaction, so two changes to one claim at once happen one after the other. */
    public Claim find(String sheetId, long id) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ? FOR UPDATE", Claims::claim, sheetId, id)
                .stream().findFirst().orElse(null);
    }

    /** The person's claims, newest first, each locked for the rest of the transaction. */
    public List<Claim> ofPerson(String sheetId, long personId) {
        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC FOR UPDATE",
                Claims::claim, sheetId, personId);
    }

    /** Unbind every claim of the person a statement binds: each shows its live figure again. */
    public void unbind(String sheetId, long personId) {
        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ? AND stated",
                sheetId, personId);
    }

    /** Whether the person has a SETTLED claim with this number: one a correction may correct. */
    public boolean settled(String sheetId, long personId, String number) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ? AND status = 'SETTLED'",
                Integer.class, sheetId, personId, number);
        return n != null && n > 0;
    }

    /** Whether a claim on the sheet other than `ownId` (null: any) has this reference, without regard to case. */
    public boolean refUsed(String sheetId, String ref, Long ownId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND LOWER(ref) = LOWER(?) AND id <> ?",
                Integer.class, sheetId, ref, ownId != null ? ownId : -1L);
        return n != null && n > 0;
    }

    /** The date of the person's claim with this number, or null when there is none. */
    public LocalDate dateOf(String sheetId, long personId, String number) {
        return jdbc.query("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?",
                (rs, i) -> rs.getDate("claim_date").toLocalDate(), sheetId, personId, number)
                .stream().findFirst().orElse(null);
    }

    /** Move the claim to its (new) person: unbound from any statement, and listed as that person's newest claim. */
    public void reassign(Claim claim) {
        jdbc.update("UPDATE claim SET person_id = ?, number = ?, stated = FALSE, stated_due = NULL, listed = NEXT VALUE FOR claim_listed WHERE id = ?",
                claim.getPersonId(), claim.getNumber(), claim.getId());
    }

    /** Release every editor's lock on the sheet's claims: the sheet's today has changed. */
    public void unlockAll(String sheetId) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
    }

    /** Release the user's locks on the person's other claims: the person's one claim form edits one claim at a time. */
    public void unlockOthers(String sheetId, long personId, String user, long keptId) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND person_id = ? AND locked_by = ? AND id <> ?",
                sheetId, personId, user, keptId);
    }

    /** Fix the claim's due-by again, at the date it now has. */
    public void redue(Claim claim) {
        jdbc.update("UPDATE claim SET due_by = ? WHERE id = ?", Date.valueOf(claim.getDueBy()), claim.getId());
    }

    /** Record the day the claim was last reminded. */
    public void remind(Claim claim) {
        jdbc.update("UPDATE claim SET reminded_on = ? WHERE id = ?", Date.valueOf(claim.getRemindedOn()), claim.getId());
    }

    /** The number the sheet's next bulk settle batch takes: one past its last. */
    public int nextBatch(String sheetId) {
        Integer last = jdbc.queryForObject("SELECT MAX(batch) FROM claim WHERE sheet_id = ?", Integer.class, sheetId);
        return last == null ? 1 : last + 1;
    }

    /** Insert a new claim (assigning its id) or update an existing one. */
    public void save(Claim claim) {
        if (claim.getId() != null) {
            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ?, locked_by = ?, ref = ?, tags = ?, tags_used = ?, void_reason = ?, edited_by = ?, batch = ? WHERE id = ?",
                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
                    claim.getNumber(), claim.getDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
                    claim.getDeferredUntil() != null ? Date.valueOf(claim.getDeferredUntil()) : null, claim.getProofs(), claim.getLockedBy(), claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(), claim.getEditedBy(), claim.getBatch(), claim.getId());
            return;
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, due_by, number, opened_by, split_from, late_entry, ref, tags, tags_used, due_terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, claim.getSheetId());
            ps.setLong(2, claim.getPersonId());
            ps.setBigDecimal(3, claim.getAmount());
            ps.setDate(4, Date.valueOf(claim.getDate()));
            ps.setString(5, claim.getNote());
            ps.setString(6, claim.getStatus().name());
            ps.setString(7, claim.getCorrects());
            ps.setDate(8, Date.valueOf(claim.getDueBy()));
            ps.setString(9, claim.getNumber());
            ps.setString(10, claim.getOpenedBy());
            ps.setString(11, claim.getSplitFrom());
            ps.setBoolean(12, claim.isLateEntry());
            ps.setString(13, claim.getRef());
            ps.setString(14, claim.getTags());
            ps.setString(15, claim.getTagsUsed());
            ps.setObject(16, claim.getDueTerms(), Types.INTEGER);
            return ps;
        }, keys);
        claim.setId(keys.getKey().longValue());
    }

    private static Claim claim(ResultSet rs, int i) throws SQLException {
        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
                rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
                ClaimStatus.valueOf(rs.getString("status")), rs.getString("number"),
                rs.getBigDecimal("due"), rs.getString("opened_by"));
        claim.setStated(rs.getBoolean("stated"));
        claim.setStatedDue(rs.getBigDecimal("stated_due"));
        claim.setCorrects(rs.getString("corrects"));
        claim.setDueBy(rs.getDate("due_by").toLocalDate());
        claim.setProofs(rs.getInt("proofs"));
        claim.setSplitFrom(rs.getString("split_from"));
        claim.setLockedBy(rs.getString("locked_by"));
        claim.setLateEntry(rs.getBoolean("late_entry"));
        claim.setRef(rs.getString("ref"));
        claim.setTagsUsed(rs.getString("tags_used"));
        claim.setTags(rs.getString("tags"));
        claim.setVoidReason(rs.getString("void_reason"));
        claim.setEditedBy(rs.getString("edited_by"));
        int terms = rs.getInt("due_terms");
        claim.setDueTerms(rs.wasNull() ? null : terms);
        int batch = rs.getInt("batch");
        claim.setBatch(rs.wasNull() ? null : batch);
        Date reminded = rs.getDate("reminded_on");
        claim.setRemindedOn(reminded != null ? reminded.toLocalDate() : null);
        Date until = rs.getDate("deferred_until");
        Date today = rs.getDate("sheet_today");
        claim.setDeferredUntil(until != null ? until.toLocalDate() : null);
        claim.setDeferred(until != null && today != null && today.toLocalDate().isBefore(until.toLocalDate()));
        return claim;
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet. `id` is null until the person is first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    /** The person's grades by the date each is in force from; LocalDate.MIN for the first one,
     *  which applies from the beginning of time. */
    private TreeMap<LocalDate, String> grades = new TreeMap<>();
    /** The sheet's today as it was when the person was read (null: the person is new). */
    private LocalDate today;
    /** A grade this save records, from its date (null: the save records none). */
    private DatedGrade newGrade;
    private int version;
    /** The person's own terms in days (null: none). */
    private Integer terms;
    /** Whether this save changes the person's own terms. */
    private boolean termsChanged;
    /** The person's contact (null: none). */
    private String contact;
    /** Whether this save changes the person's contact. */
    private boolean contactChanged;
    /** The person's tags, lower-cased, sorted and comma separated (null: none). */
    private String tags;
    /** The sheet the person was transferred from, and the name they had there (null: not transferred). */
    private String originSheet;
    private String originName;
    private int statementCount;
    private BigDecimal statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    /** The person's ended retirements, in the order they ended. */
    private List<PastRetirement> pastRetirements = new ArrayList<>();
    private List<Hold> holds = new ArrayList<>();
    private List<String> snapshots = new ArrayList<>();
    private List<Long> patronIds = new ArrayList<>();
    /** The person's aliases, sorted as names are compared. */
    private List<String> aliases = new ArrayList<>();
    /** Whether the person's name or an alias is used on another sheet of their sheet's tree. */
    private boolean clashing;

    public Person(Long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(Long id, String sheetId, String name, String grade, int version) {
        this.version = version;
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        if (grade != null) this.grades.put(LocalDate.MIN, grade);
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    /** The grade in force on the sheet's today. */
    public String getGrade() { return today == null ? grades.lastEntry().getValue() : gradeOn(today); }
    /** The grade in force on `date`: the one from the latest date on or before it, the first one
     *  applying from the beginning of time. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> e = grades.floorEntry(date);
        return e != null ? e.getValue() : grades.firstEntry().getValue();
    }
    /** The first grade the person was given. */
    public String getFirstGrade() { return grades.firstEntry().getValue(); }
    public TreeMap<LocalDate, String> getGrades() { return grades; }
    public void setGrades(TreeMap<LocalDate, String> grades) { this.grades = grades; }
    public void setToday(LocalDate today) { this.today = today; }
    public DatedGrade getNewGrade() { return newGrade; }
    /** Record `grade` from `from` with the next save, replacing any grade from that same date. */
    public void recordGrade(String grade, LocalDate from) {
        this.newGrade = new DatedGrade(grade, from);
        LocalDate key = grades.isEmpty() ? LocalDate.MIN : from;
        grades.put(key, grade);
    }
    /** The person's own terms in days; null when they have none. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    public boolean isTermsChanged() { return termsChanged; }
    /** Give the person these terms (null: none) with the next save, noting whether they change. */
    public void changeTerms(Integer terms) {
        this.termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }
    /** The person's contact; null when they have none. */
    public String getContact() { return contact; }
    public void setContact(String contact) { this.contact = contact; }
    /** The sheet the person was transferred from; null when they were not transferred here. */
    public String getOriginSheet() { return originSheet; }
    /** The name the person had on the sheet they were transferred from (null: not transferred). */
    public String getOriginName() { return originName; }
    public void setOrigin(String sheet, String name) { this.originSheet = sheet; this.originName = name; }
    public boolean isContactChanged() { return contactChanged; }
    /** Give the person this contact (null: none) with the next save, noting whether it changes. */
    public void changeContact(String contact) {
        this.contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }
    /** The person's tags, lower-cased, sorted and comma separated; null when they have none. */
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }
    /** How many times the person has been saved since added. */
    public int getVersion() { return version; }
    public void setVersion(int version) { this.version = version; }
    /** How many statements have been taken for the person. */
    public int getStatementCount() { return statementCount; }
    public void setStatementCount(int statementCount) { this.statementCount = statementCount; }
    /** The last statement's due-total; null when none was taken or it was n/a. */
    public BigDecimal getStatedTotal() { return statedTotal; }
    public void setStatedTotal(BigDecimal statedTotal) { this.statedTotal = statedTotal; }
    /** The sheet's today when the last statement was taken; null when none was. */
    public LocalDate getStatementDate() { return statementDate; }
    public void setStatementDate(LocalDate statementDate) { this.statementDate = statementDate; }
    /** The date the person is retired from; null when they are not retired. Set at all, they count
     *  as retired at once, whatever the date. */
    public LocalDate getRetiredFrom() { return retiredFrom; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    /** The person's ended retirements, in the order they ended. */
    public List<PastRetirement> getPastRetirements() { return pastRetirements; }
    public void setPastRetirements(List<PastRetirement> pastRetirements) { this.pastRetirements = pastRetirements; }
    /** End the person's retirement on `on`: they are no longer retired, and it is kept as a past one. */
    public void unretire(LocalDate on) {
        pastRetirements.add(new PastRetirement(retiredFrom, on));
        retiredFrom = null;
    }
    /** Whether the sheet's today (as read) has reached the person's retirement date: from then their
     *  OPEN and PENDING claims leave the live totals, as a hold's would. */
    public boolean retiredOut() {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }
    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** The person's holds, in the order they were added. */
    public List<Hold> getHolds() { return holds; }
    public void setHolds(List<Hold> holds) { this.holds = holds; }
    /** The person's snapshot lines, oldest first: the day being left and their due-total then (n/a). */
    public List<String> getSnapshots() { return snapshots; }
    public void setSnapshots(List<String> snapshots) { this.snapshots = snapshots; }
    /** Whether `date` falls within any of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }
    /** The ids of the people the person has named as patrons, in the order they were named. */
    public List<Long> getPatronIds() { return patronIds; }
    public void setPatronIds(List<Long> patronIds) { this.patronIds = patronIds; }
    /** The person's aliases, sorted as names are compared. */
    public List<String> getAliases() { return aliases; }
    public void setAliases(List<String> aliases) { this.aliases = aliases; }
    public boolean isClashing() { return clashing; }
    public void setClashing(boolean clashing) { this.clashing = clashing; }

    /** Whether a claim of the person's counts in the live totals: OPEN, PENDING and SETTLED ones do,
     *  but not a deferred one, nor an OPEN or PENDING one dated within one of the person's holds, nor
     *  one once the sheet's today has reached their retirement date, unless a statement binds it. */
    public boolean counts(Claim claim) {
        return counts(claim, claim.getStatus());
    }

    /** Whether a claim of the person's counts as it would with `status` (null: none, it does not
     *  count): by the live rules above, but with that status in place of the claim's own. */
    public boolean counts(Claim claim, ClaimStatus status) {
        if (status == null) return false;
        if (!status.counts() || claim.isDeferred()) return false;
        if (!status.isOpen() || !(heldOn(claim.getDate()) || retiredOut())) return true;
        return claim.isStated() && status != ClaimStatus.PENDING;
    }

    /** Refuses a claim dated after the person's retirement date, or after the from and before the
     *  to of one of their past retirements. */
    public void refuseRetired(LocalDate claimDate) throws PersonRetiredException {
        if (retiredFrom != null && claimDate.isAfter(retiredFrom)) {
            throw new PersonRetiredException(name, retiredFrom);
        }
        for (PastRetirement past : pastRetirements) {
            if (past.covers(claimDate)) throw new PersonRetiredException(name, past);
        }
    }

    /** A grade in force from a date (null: from the beginning of time). */
    public record DatedGrade(String grade, LocalDate from) {
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.voidreason.VoidReasons;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim its number (see {@link ClaimNumbers}); a voided claim keeps it (and it is never reused).
 *  Settling fixes the claim's due at the figure it has then: the one its person's last statement
 *  bound it to, else its person's grade's rate in force on the claim's date, plus its late charge then, at least the sheet's floor; with no rate it stays live. The user who opened a claim, or last edited it, may not settle it.
 *  When a clerk settles a claim whose due is over the sheet's clerk limit (a due of n/a is within any
 *  limit) it goes PENDING instead, its due still live; a steward settles anything. Only a steward
 *  approves a PENDING claim (it settles, its due fixed at its live figure then, plus its late charge, at least the floor),
 *  and never the user who opened it or last edited it; a rejection sends it back to OPEN, bound again by the last
 *  statement if that bound it.
 *  A claim whose due is above the proof threshold in force on its date (its person's grade's then when
 *  one is set, else the sheet's) cannot be settled or
 *  approved while it has no proofs (refused before the clerk limit is considered).
 *  A claim whose due is above the sheet's note threshold in force on its date cannot be opened while
 *  its note is empty.
 *  A deferred claim cannot be settled until the sheet's today reaches its deferred-until date.
 *  Only a steward may void a SETTLED claim, and only while the sheet's today is within 7 days of its
 *  settlement (its status log's SETTLED date); its frozen due then leaves every total.
 *  A claim due by in a period with a cap cannot be opened while its person already has that many
 *  OPEN or PENDING claims due by in it.
 *  A claim due by in a closed period cannot change status at all. Opening, settling and voiding are
 *  only for the roles the sheet's permission matrix allows (see {@link Settings#allows}).
 *  While the sheet's list of void reasons is not empty, a void needs a reason from it, which the
 *  claim keeps.
 *  A DRAFT claim can be deleted; a DELETED one restored to DRAFT only on the sheet's today it was
 *  deleted (its status log's last DELETED date). */
public class ApplyClaimStatus {
    /** How many days after its settlement (the status log's SETTLED date) a steward may still void a claim. */
    static final int SETTLED_VOID_DAYS = 7;

    public void apply(@Val ClaimStatusChange change, @Val Claim claim, ClaimNumbers numbers, People people,
            Figures figures, ClosedPeriods closedPeriods, Settings settings, ClaimLog log, Sheets sheets,
            VoidReasons voidReasons)
            throws ClaimStatusRefusedException, PeriodClosedException {
        closedPeriods.refuse(claim.getSheetId(), claim.getDueBy());
        if (!change.action().allowedFrom(claim.getStatus())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), change.action());
        }
        String perm = change.action() == ClaimAction.OPEN ? "open" : change.action() == ClaimAction.SETTLE ? "settle"
                : change.action() == ClaimAction.VOID ? "void" : null;
        if (perm != null && !settings.allows(claim.getSheetId(), perm, change.user())) {
            throw new ClaimStatusRefusedException("Your role may not " + perm + " a claim");
        }
        if (change.action() == ClaimAction.OPEN && (claim.getNote() == null || claim.getNote().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
            if (threshold != null) {
                String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
                BigDecimal due = figures.due(claim, grade);
                if (due != null && due.compareTo(threshold) > 0) {
                    throw new ClaimStatusRefusedException("A claim whose due is over the note threshold needs a note");
                }
            }
        }
        if (change.action() == ClaimAction.OPEN
                && closedPeriods.atCap(claim.getSheetId(), claim.getPersonId(), claim.getDueBy())) {
            throw new ClaimStatusRefusedException("The person already has as many open claims in the period as its cap allows");
        }
        if (change.action() == ClaimAction.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
            LocalDate settled = log.settledOn(claim);
            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD || settled == null
                    || sheets.today(claim.getSheetId()).isAfter(settled.plusDays(SETTLED_VOID_DAYS))) {
                throw new ClaimStatusRefusedException("Only a steward can void a settled claim, and only within "
                        + SETTLED_VOID_DAYS + " days of its settlement");
            }
        }
        if (change.action() == ClaimAction.RESTORE) {
            LocalDate deleted = log.lastOn(claim, ClaimStatus.DELETED);
            if (deleted == null || !deleted.equals(sheets.today(claim.getSheetId()))) {
                throw new ClaimStatusRefusedException("A deleted claim can be restored only on the day it was deleted");
            }
        }
        String voidReason = null;
        if (change.action() == ClaimAction.VOID && !voidReasons.onSheet(claim.getSheetId()).isEmpty()) {
            if (change.reason() == null || !voidReasons.has(claim.getSheetId(), change.reason())) {
                throw new ClaimStatusRefusedException("A void needs a void reason from the sheet's list");
            }
            voidReason = change.reason();
        }
        if (change.action() == ClaimAction.SETTLE && claim.isDeferred()) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
        }
        if (change.action() == ClaimAction.SETTLE && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(change.user())) {
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (change.action() == ClaimAction.SETTLE && change.user().equals(claim.getEditedBy())) {
            throw new ClaimStatusRefusedException("The user who last edited a claim cannot settle it");
        }
        if (change.action() == ClaimAction.APPROVE) {
            if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(change.user())) {
                throw new ClaimStatusRefusedException("The user who opened a claim cannot approve it");
            }
            if (change.user().equals(claim.getEditedBy())) {
                throw new ClaimStatusRefusedException("The user who last edited a claim cannot approve it");
            }
            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
                throw new ClaimStatusRefusedException("Only a steward can approve a pending claim");
            }
        }
        BigDecimal due = null;
        boolean pending = false;
        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            // Figures.due: from the bound figure for an OPEN claim, the live one for a PENDING claim.
            due = figures.due(claim, grade);
            // Before the clerk limit: a claim refused for want of a proof never goes PENDING.
            BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), grade, claim.getDate());
            if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
                throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof");
            }
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
                    && settings.role(claim.getSheetId(), change.user()) == Role.CLERK;
        }
        claim.setStatus(pending ? ClaimStatus.PENDING : change.action().to());
        // Settled one at a time: in no batch (a bulk settle sets its batch after this).
        if (change.action() == ClaimAction.SETTLE) claim.setBatch(null);
        if (change.action() == ClaimAction.VOID) claim.setVoidReason(voidReason);
        if (change.action() == ClaimAction.OPEN) {
            claim.setNumber(numbers.next(claim));
            claim.setOpenedBy(change.user());
        }
        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
            claim.setDue(due);
        }
    }
}

