package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT → OPEN → SETTLED (or, settled by a clerk over the clerk
 *  limit, OPEN → PENDING, which a steward approves to SETTLED or rejects back to OPEN), and DRAFT,
 *  OPEN or PENDING → VOID; a steward may also void a SETTLED claim within 7 days of its settlement.
 *  A DRAFT can be DELETED, and restored to DRAFT on the same sheet's today; a DELETED claim counts nowhere. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED;

    /** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is still open: OPEN, or PENDING (handled like an OPEN one: it goes overdue,
     *  bears the late charge and a hold takes it out of the totals). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

/** A status change asked of a claim: the status it moves to, the statuses it may move from, and
 *  the audit event it writes. */
public enum ClaimAction {
    OPEN(ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.DRAFT),
    SETTLE(ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.OPEN),
    APPROVE(ClaimStatus.SETTLED, "CLAIM_APPROVED", ClaimStatus.PENDING),
    REJECT(ClaimStatus.OPEN, "CLAIM_REJECTED", ClaimStatus.PENDING),
    VOID(ClaimStatus.VOID, "CLAIM_VOIDED", ClaimStatus.DRAFT, ClaimStatus.OPEN, ClaimStatus.PENDING,
            ClaimStatus.SETTLED),
    DELETE(ClaimStatus.DELETED, "CLAIM_DELETED", ClaimStatus.DRAFT),
    RESTORE(ClaimStatus.DRAFT, "CLAIM_RESTORED", ClaimStatus.DELETED);

    private final ClaimStatus to;
    private final String event;
    private final ClaimStatus[] from;

    ClaimAction(ClaimStatus to, String event, ClaimStatus... from) {
        this.to = to;
        this.event = event;
        this.from = from;
    }

    public ClaimStatus to() { return to; }
    public String event() { return event; }

    public boolean allowedFrom(ClaimStatus status) {
        for (ClaimStatus s : from) {
            if (s == status) return true;
        }
        return false;
    }
}
package net.officefloor.hq.app.claim;


/** The number a claim gets when it is opened. While the sheet's period numbering from is set and
 *  the sheet's today is on or after it, the claim is numbered within the period its due-by falls in
 *  (<period name>-<n>), or X-<n> when it falls in none; otherwise it takes the next number within
 *  the fiscal year its due-by falls in (FY<yyyy>-<n>, counting from 1 each fiscal year, the sequence
 *  shared across the sheet's tree). */
@Service
public class ClaimNumbers {

    /** The sequence of claims in no period. */
    public static final String NO_PERIOD = "X";

    private final Sheets sheets;
    private final Settings settings;
    private final Periods periods;

    public ClaimNumbers(Sheets sheets, Settings settings, Periods periods) {
        this.sheets = sheets;
        this.settings = settings;
        this.periods = periods;
    }

    public String next(Claim claim) {
        String sheetId = claim.getSheetId();
        LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            int fy = fiscalYear(claim.getDueBy(), settings.fiscalStartMonth(sheetId));
            return "FY" + fy + "-" + sheets.nextFiscalNumber(sheetId, fy);
        }
        String seq = periods.onSheet(sheetId).stream().filter(p -> p.contains(claim.getDueBy()))
                .map(Period::name).findFirst().orElse(NO_PERIOD);
        return seq + "-" + sheets.nextPeriodNumber(sheetId, seq);
    }

    /** The fiscal year (the yyyy of FY<yyyy>, the calendar year its first day falls in) a date is in. */
    static int fiscalYear(LocalDate date, int startMonth) {
        return date.getMonthValue() >= startMonth ? date.getYear() : date.getYear() - 1;
    }
}
package net.officefloor.hq.app.claim;


/** The due-by a claim is fixed with when it is added; it also decides the claim's period. */
public final class DueBy {

    private DueBy() {
    }

    /** The due-by of a claim of `person` dated `date`: the terms-th business day after its date,
     *  taking the person's own terms, else the terms of their grade then, else the sheet's terms then,
     *  and skipping every Saturday, Sunday and holiday on the sheet now. */
    public static LocalDate of(Person person, LocalDate date, Settings settings, Holidays holidays) {
        return holidays.businessDaysAfter(person.getSheetId(), date, terms(person, date, settings));
    }

    /** The terms a claim of `person` dated `date` is fixed with: the person's own, else those of their
     *  grade then, else the sheet's then. */
    public static int terms(Person person, LocalDate date, Settings settings) {
        Integer own = person.getTerms();
        return own != null ? own : settings.terms(person.getSheetId(), person.gradeOn(date), date);
    }
}
package net.officefloor.hq.app.claim;


/** A claim as the screen sees it: the amount with two decimals, the date as yyyy-mm-dd,
 *  the status as DRAFT, OPEN, PENDING, SETTLED or VOID, the number null when the claim has none, the due
 *  fixed at settling with two decimals, null when it has none (its due is worked out live),
 *  who opened it, null while it has not been opened, whether its person's last statement binds it
 *  and the figure it binds it to (two decimals; null when unbound or bound to n/a), and the number
 *  of the claim a correction corrects (null when it is not a correction), and whether its live
